import 'package:flutter/material.dart';
import 'presentation/criterivox_theme.dart';
enum CollaborationDestination{meetingHall,projectRooms,sharedWorkspaces}
class CollaborationCommonsPage extends StatelessWidget{final CollaborationDestination destination;final VoidCallback? onDecisionDesk;const CollaborationCommonsPage({super.key,required this.destination,this.onDecisionDesk});String get title=>switch(destination){CollaborationDestination.meetingHall=>'MEETING HALL',CollaborationDestination.projectRooms=>'PROJECT ROOMS',CollaborationDestination.sharedWorkspaces=>'SHARED WORKSPACES'};String get purpose=>switch(destination){CollaborationDestination.meetingHall=>'A structured place for people to meet, review context and challenge a live question.',CollaborationDestination.projectRooms=>'A project-scoped collaboration space for work, artifacts, milestones and decisions.',CollaborationDestination.sharedWorkspaces=>'A reusable shared working environment for teams that need a common context.'};IconData get icon=>switch(destination){CollaborationDestination.meetingHall=>Icons.table_restaurant_outlined,CollaborationDestination.projectRooms=>Icons.folder_shared_outlined,CollaborationDestination.sharedWorkspaces=>Icons.space_dashboard_outlined};@override Widget build(BuildContext context){final t=CriterivoxTheme.of(context);return SingleChildScrollView(key:ValueKey(destination),padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Row(children:[Icon(icon,color:t.primary,size:30),const SizedBox(width:12),Expanded(child:Text(title,style:TextStyle(color:t.text,fontSize:26,fontWeight:FontWeight.w800)))]),const SizedBox(height:8),Text(purpose,style:TextStyle(color:t.mutedText,fontSize:12,height:1.45)),const SizedBox(height:18),_panel(t,'WORKSPACE BOUNDARY',Column(crossAxisAlignment:CrossAxisAlignment.start,children:[_row(t,'Human participants','Owner, Resident and Guest roles remain governed by the existing Human Residence boundary.'),_row(t,'Shared context','This destination keeps collaboration context distinct from a private residence.'),_row(t,'Criterivox support','Existing collaboration and character-runtime capabilities remain behind their established boundaries.')])) ,const SizedBox(height:14),_panel(t,'AVAILABLE WORK',Wrap(spacing:10,runSpacing:10,children:[OutlinedButton.icon(onPressed:() {},icon:const Icon(Icons.fact_check_outlined),label:const Text('Review shared context')),OutlinedButton.icon(onPressed:() {},icon:const Icon(Icons.account_tree_outlined),label:const Text('Inspect activity')),OutlinedButton.icon(onPressed:() {},icon:const Icon(Icons.question_mark_rounded),label:const Text('Challenge a proposal')),if(onDecisionDesk!=null)OutlinedButton.icon(onPressed:onDecisionDesk,icon:const Icon(Icons.balance_rounded),label:const Text('Open Decision Desk'))]))]));}Widget _panel(CriterivoxTheme t,String title,Widget child)=>Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:t.surface,borderRadius:BorderRadius.circular(20),border:Border.all(color:t.border)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:TextStyle(color:t.primary,fontSize:9,fontWeight:FontWeight.w900,letterSpacing:1.2)),const SizedBox(height:12),child]));Widget _row(CriterivoxTheme t,String a,String b)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[SizedBox(width:130,child:Text(a,style:TextStyle(color:t.text,fontSize:10,fontWeight:FontWeight.w800))),Expanded(child:Text(b,style:TextStyle(color:t.mutedText,fontSize:10,height:1.4)))]));}